Section STORE.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (lo ARGS PK TR SB Fr n : Z) (src junk : list byte) (m : word -> option byte).
  Hypothesis LO : ltac2:(zQ "40!hc!jl3!jua!krc@2$2@2$1?2lo+l0@2$3@1$0#k0?2sp").
  Hypothesis IMGLO : ltac2:(zQ "20!ll4!jua@2$1$0?2lo").
  Hypothesis ARGSR : ltac2:(zQ "60!jua!vb!hc!jl3!ku2!krc@2$1@2$0@2$5@1$2#k0?2sp?4ARGS@2$0@2$3?4ARGS+h0@2$4+2+k0").
